import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long p = nextLong(), q = nextLong(), budget = nextLong();
        // Skips needed to win a warehouse: floor((r - 1) / p) with r = (v - 1) mod (p + q) + 1.
        long[] costs = new long[n];
        for (int i = 0; i < n; i++) costs[i] = ((nextLong() - 1) % (p + q)) / p;
        Arrays.sort(costs);
        long answer = 0;
        for (long c : costs) {
            if (c > budget) break;
            budget -= c;
            answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, p, q, budget := nextInt(), nextInt(), nextInt(), nextInt()
	// Skips needed to win a warehouse: floor((r - 1) / p) with r = (v - 1) mod (p + q) + 1.
	costs := make([]int, n)
	for i := range costs {
		costs[i] = ((nextInt() - 1) % (p + q)) / p
	}
	sort.Ints(costs)
	answer := 0
	for _, c := range costs {
		if c > budget {
			break
		}
		budget -= c
		answer++
	}
	fmt.Println(answer)
}
